  for (var i = 0; i < reasons.length; i++) {
    if (unique.indexOf(reasons[i]) === -1) unique.push(reasons[i]);
  }

  return {
    guard_status: unique.length === 0 ? 'PASS' : 'BLOCKED',
    block_reasons: unique
